import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";
import { decodeFragment, verifyBundle } from "../src/bundle.js";
import { JsonNumber } from "../src/json.js";
import type { WitnessReceiptResult } from "../src/witness.js";

// Strict verifyBundle on parent-log-witness/v1 against
// vectors/bundle/parent-log-witness (generated by
// python/scripts/generate_bundle_parent_witness_vectors.py), compared as its
// README says.
const DIR = resolve(
  process.cwd(),
  "..",
  "vectors",
  "bundle",
  "parent-log-witness",
);

type Case = {
  id: string;
  options: { witness_directory: boolean };
  bundle: unknown;
  expect: {
    verdict: string;
    parent_witness: unknown;
    extension_status?: string;
    witnesses?: { status: string; findings: string[] };
  };
};
// Read with the library's own Bundle decoder (decodeFragment), not
// JSON.parse: a float-spelled number such as neg-leaf-size-float's `4.0`
// stays a JsonNumber, as it does for a Bundle read from a URL fragment,
// instead of becoming the integer 4.
const vectors = decodeFragment(
  readFileSync(resolve(DIR, "vectors.json")).toString("base64url"),
) as { witness_directory: unknown; cases: Case[] };
const manifest = JSON.parse(
  readFileSync(resolve(DIR, "manifest.json"), "utf8"),
) as { case_count: number };

const receiptFields = (r: WitnessReceiptResult) => ({
  ts_url: r.tsUrl,
  binding: r.binding,
  status: r.status,
  grade: r.grade,
  key_id: r.keyId,
  registration_time: r.registrationTime,
  registration_time_reason: r.registrationTimeReason,
});

describe("parent-log-witness/v1 vectors", () => {
  it("runs every case the manifest counts", () => {
    expect(vectors.cases).toHaveLength(manifest.case_count);
  });

  it("keeps neg-leaf-size-float's 4.0 a float", () => {
    const testCase = vectors.cases.find((c) => c.id === "neg-leaf-size-float")!;
    const bundle = testCase.bundle as {
      extensions: Record<string, { size: unknown }>;
    };
    const size = bundle.extensions["parent-log-witness/v1"]!.size;
    expect(size).toBeInstanceOf(JsonNumber);
    expect((size as JsonNumber).raw).toBe("4.0");
  });

  it.each(vectors.cases.map((c) => [c.id, c] as const))(
    "%s",
    async (_id, testCase) => {
      const result = await verifyBundle(testCase.bundle, {
        strict: true,
        ...(testCase.options.witness_directory
          ? { witnessDirectory: vectors.witness_directory }
          : {}),
      });
      const { strict } = result;
      expect(strict.verdict).toBe(testCase.expect.verdict);
      const parent = strict.parentWitness;
      expect(
        parent === null
          ? null
          : {
              status: parent.status,
              findings: parent.findings,
              extent: parent.extent,
              receipts: parent.receipts.map(receiptFields),
            },
      ).toEqual(testCase.expect.parent_witness);
      const extension = result.extensions.find(
        (e) => e.kind === "parent-log-witness/v1",
      );
      if (testCase.expect.extension_status !== undefined)
        expect(extension?.status).toBe(testCase.expect.extension_status);
      if (testCase.expect.witnesses !== undefined)
        expect({
          status: strict.witnesses?.status,
          findings: strict.witnesses?.findings,
        }).toEqual(testCase.expect.witnesses);
      // Plain mode never interprets the block.
      if (extension !== undefined) {
        const plain = await verifyBundle(testCase.bundle);
        expect(
          plain.extensions.find((e) => e.kind === "parent-log-witness/v1")
            ?.status,
        ).toBe("uninterpreted");
      }
    },
  );
});
